breach.segment:
// SQL Server engine marker: excludes MySQL / PostgreSQL replicas that share this metric
WHERE ss > 0 AND lag_n > 0
// Breach conditions (either):
//  - lagging: the replica stayed behind for the WHOLE window (minimum lag >= 120 s),
//    i.e. it is not catching up after bursts. Requires ~5 minutes of samples.
//    Lower for latency-sensitive reads; raise for cross-region replicas.
//  - stopped: the latest sample is negative, meaning replication is inactive.
| EVAL lag_breach = lag_n >= 5 AND lag_min >= 120,
       stopped = lag_last < 0
| WHERE lag_breach OR stopped
| EVAL reason = CASE(stopped, "replication inactive (negative lag)", "replica lagging")
| KEEP database_id, reason, lag_min, lag_max, lag_last, network_lag_max
| SORT lag_max DESC
| LIMIT 100
